const http = require("http");
const IMG = {"01":"","02":"","03":"","04":"","05":"","06":"","07":"","08":"","09":"","10":""};
const buf = {};
for (const k in IMG) buf[k] = Buffer.from(IMG[k], "base64");
const PORT = process.env.PORT || 3000;
http.createServer((req, res) => {
  const m = req.url.match(/^\/p\/(\d{2})\.jpg$/);
  if (m && buf[m[1]]) {
    res.writeHead(200, {
      "Content-Type": "image/jpeg",
      "Cache-Control": "public, max-age=31536000, immutable",
      "Access-Control-Allow-Origin": "*"
    });
    return res.end(buf[m[1]]);
  }
  if (req.url === "/") {
    res.writeHead(200, { "Content-Type": "text/html" });
    return res.end("<h1>Viva Viager media</h1>" + Object.keys(buf).map(k => '<a href="/p/'+k+'.jpg">'+k+'</a>').join(" "));
  }
  res.writeHead(404); res.end("Not found");
}).listen(PORT, () => console.log("media up on " + PORT));
